<section class="content-header"><h1><i class="fa fa-gift"></i> Reporte de cortesías</h1></section><section class="content">
<div class="alert alert-info"><i class="fa fa-info-circle"></i> Este reporte identifica cortesías por su registro explícito en <b>pasaje_cortesia_bitacora</b>. Un pasaje o venta con importe Bs 0 no se considera cortesía por ese solo hecho.</div>
<div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="usuario_id" class="form-control"><option value="0">Todos los usuarios</option><?php foreach($listas['usuarios'] as $u):?><option value="<?php echo $u['usuario_id'];?>" <?php echo $filtros['usuario_id']==$u['usuario_id']?'selected':'';?>><?php echo html_escape($u['usuario_nombre']);?></option><?php endforeach;?></select> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r):?><option value="<?php echo $r['ruta_id'];?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':'';?>><?php echo html_escape($r['ruta_nombre']);?></option><?php endforeach;?></select> <select name="motivo_id" class="form-control"><option value="0">Todos los motivos</option><?php foreach($listas['motivos'] as $m):?><option value="<?php echo $m['cortesiamotivo_id'];?>" <?php echo $filtros['motivo_id']==$m['cortesiamotivo_id']?'selected':'';?>><?php echo html_escape($m['cortesiamotivo_nombre']);?></option><?php endforeach;?></select> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="row"><div class="col-md-3"><div class="info-box"><span class="info-box-icon bg-aqua"><i class="fa fa-gift"></i></span><div class="info-box-content"><span class="info-box-text">Cortesías emitidas</span><span class="info-box-number"><?php echo number_format($resumen['cortesias'],0,',','.');?></span></div></div></div><div class="col-md-3"><div class="info-box"><span class="info-box-icon bg-yellow"><i class="fa fa-ticket"></i></span><div class="info-box-content"><span class="info-box-text">Valor tarifario</span><span class="info-box-number">Bs <?php echo number_format($resumen['valor_tarifario'],2,',','.');?></span></div></div></div><div class="col-md-3"><div class="info-box"><span class="info-box-icon bg-green"><i class="fa fa-money"></i></span><div class="info-box-content"><span class="info-box-text">Importe cobrado</span><span class="info-box-number">Bs <?php echo number_format($resumen['cobrado'],2,',','.');?></span></div></div></div><div class="col-md-3"><div class="info-box"><span class="info-box-icon bg-red"><i class="fa fa-arrow-down"></i></span><div class="info-box-content"><span class="info-box-text">Valor otorgado</span><span class="info-box-number">Bs <?php echo number_format($resumen['beneficio'],2,',','.');?></span></div></div></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Detalle de cortesías</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_cortesias/csv').'?'.http_build_query($filtros);?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Fecha</th><th>Ticket</th><th>Pasajero</th><th>Ruta</th><th>Motivo</th><th class="text-right">Tarifa original</th><th class="text-right">Cobrado</th><th>Usuario</th></tr></thead><tbody><?php foreach($detalle as $r):?><tr><td><?php echo html_escape($r['fecha']);?></td><td><b><?php echo html_escape($r['ticket']);?></b></td><td><?php echo html_escape($r['pasajero']);?><br><small><?php echo html_escape($r['documento']);?></small></td><td><?php echo html_escape($r['ruta']);?></td><td><?php echo html_escape($r['motivo']);?></td><td class="text-right">Bs <?php echo number_format($r['tarifa_original'],2,',','.');?></td><td class="text-right">Bs <?php echo number_format($r['importe_cobrado'],2,',','.');?></td><td><?php echo html_escape($r['usuario']);?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}table{font-size:9px!important}</style>
